function bestHand(points: number[], k: number): number {
  const n = points.length;
  let best = 0;
  for (let i = 0; i <= k; i++) {
    let s = 0;
    for (let j = 0; j < i; j++) s += points[j];
    for (let j = n - (k - i); j < n; j++) s += points[j];
    best = Math.max(best, s);
  }
  return best;
}

