function bestHand(points: number[], k: number): number {
  const n = points.length, w = n - k;
  let total = 0, win = 0;
  for (let i = 0; i < n; i++) total += points[i];
  for (let i = 0; i < w; i++) win += points[i];
  let low = win;
  for (let i = w; i < n; i++) {
    win += points[i] - points[i - w];
    low = Math.min(low, win);
  }
  return total - low;
}

